"""Visible pre-save cash orientation; requests invalidated on every draft edit."""
CSS='''.po-cash{border:2px solid #c69846;background:#fff8e9;border-radius:10px;padding:18px;margin:18px 0}.po-cash-alert{padding:14px 16px;border:1px solid #b98423;border-left:6px solid #b98423;border-radius:8px;background:#fff4d8;margin:14px 0;line-height:1.5}.po-cash-alert.is-short{border-color:#b42318;background:#fff0ee;color:#78251c}.po-cash-alert strong{display:block;font-size:17px}.po-cash-alert p{margin:6px 0}.po-cash-alert button{font:inherit}.po-cash h2{font-size:19px;margin:0 0 12px}.po-cash h3{font-size:17px;margin:0 0 8px}.po-cash p{font-size:15px;line-height:1.5}.po-cash.is-short{border-color:#b42318;border-left-width:7px;background:#fff0ee;color:#78251c}.po-cash-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.po-cash-grid>div{border:1px solid #c9d5e5;padding:12px;background:white;border-radius:7px}.po-cash-grid strong{display:block;font-size:19px;margin-top:5px}.po-cash-option{background:#fff;border:1px solid #bacde0;border-radius:8px;padding:15px;margin-top:12px}.po-cash-option textarea{width:100%;box-sizing:border-box;padding:10px;line-height:1.5;font:inherit}.po-cash small{line-height:1.5;display:block}.po-cash summary{cursor:pointer;font-weight:650}.po-cash button{margin:8px 8px 0 0}@media(max-width:580px){.po-cash-grid{grid-template-columns:1fr}}'''
JS=r'''
let purchaseCashSequence=0,purchaseCashTimer,purchaseCashController;
const purchaseCashBox=document.createElement('section');purchaseCashBox.id='po-cash';purchaseCashBox.className='po-cash';purchaseCashBox.setAttribute('aria-live','polite');$('po-payments').after(purchaseCashBox);
const purchaseCashAlert=document.createElement('section');purchaseCashAlert.id='po-cash-alert';purchaseCashAlert.className='po-cash-alert';purchaseCashAlert.setAttribute('role','status');$('po-totals').after(purchaseCashAlert);
function renderPurchaseCashAlert(r){const b=r.balance_comparison,over=b&&Number(b.excess_over_balance)>0,short=r.status==='SHORTFALL';purchaseCashAlert.replaceChildren();purchaseCashAlert.className='po-cash-alert'+(short||(over&&r.status!=='WITHIN_DECLARED_SCENARIO')?' is-short':'');const h=document.createElement('strong'),p=document.createElement('p');h.textContent=short?'DÉFICIT DE TESORERÍA PREVISTO':over?(r.status==='WITHIN_DECLARED_SCENARIO'?'SUPERA EL SALDO AL CORTE; SIN DÉFICIT EN EL ESCENARIO':'LA COMPRA SUPERA EL SALDO DOCUMENTAL'):r.status==='WITHIN_DECLARED_SCENARIO'?'SIN DÉFICIT EN EL ESCENARIO DECLARADO':'TESORERÍA PENDIENTE DE COMPROBAR';p.textContent=short?'Faltan '+money(r.scenario.deficit)+' EUR para respetar el mínimo el '+stockDate(r.scenario.first_shortfall_date)+'.':over?'Compra '+money(b.purchase_amount)+' EUR · Saldo al '+stockDate(b.cutoff)+': '+money(b.opening_balance)+' EUR · Diferencia: '+money(b.excess_over_balance)+' EUR.':'';purchaseCashAlert.append(h,p);const note=document.createElement('p');note.textContent=r.status==='PENDING'?r.message: r.message||'Recalculando con las condiciones actuales…';purchaseCashAlert.append(note);if(b){const limits=document.createElement('small');limits.textContent=(b.amount_basis==='MERCHANDISE_ONLY'?'Comparación parcial: solo mercancía; portes pendientes. ':'')+'El saldo al corte no acredita disponibilidad actual. La comparación con el saldo no incluye cobros ni otros pagos; el escenario completo se muestra debajo.';purchaseCashAlert.append(limits)}const button=document.createElement('button');button.type='button';button.textContent='Ver evaluación y alternativas';button.onclick=()=>purchaseCashBox.scrollIntoView({behavior:'smooth',block:'start'});purchaseCashAlert.append(button)}
function renderPurchaseCash(box,r,editable){if(editable)renderPurchaseCashAlert(r);box.replaceChildren();box.className='po-cash'+(r.status==='SHORTFALL'?' is-short':'');const heading=document.createElement('h2');heading.textContent='EVALUACIÓN ECONÓMICA DE ESTA COMPRA';const verdict=document.createElement('h3');verdict.textContent=r.status==='SHORTFALL'?'DÉFICIT EN EL ESCENARIO PROPUESTO':r.status==='WITHIN_DECLARED_SCENARIO'?'SIN DÉFICIT EN EL ESCENARIO DECLARADO':'FALTAN DATOS PARA SIMULAR';const message=document.createElement('p');message.textContent=r.message;box.append(heading,verdict,message);if(r.scenario){const grid=document.createElement('div');grid.className='po-cash-grid';for(const [label,value] of [['Tesorería al corte',money(r.opening_balance)+' EUR'],['Mínimo configurado',money(r.treasury_minimum)+' EUR'],['Saldo mínimo del escenario',money(r.scenario.minimum_balance)+' EUR'],['Falta para respetar el mínimo',money(r.scenario.deficit)+' EUR'],['Primera fecha de déficit',r.scenario.first_shortfall_date?stockDate(r.scenario.first_shortfall_date):'Sin déficit previsto'],['Horizonte analizado',stockDate(r.cutoff)+' a '+stockDate(r.horizon_end)]]){const item=document.createElement('div'),title=document.createElement('small'),valueEl=document.createElement('strong');title.textContent=label;valueEl.textContent=value;item.append(title,valueEl);grid.append(item)}box.append(grid);const basis=document.createElement('p');basis.textContent=r.payment_basis==='DECLARED_INSTALLMENTS'?'Se simulan las cuotas que has declarado.':'HIPÓTESIS: pago único de mercancía y pago de portes, si existen, en las fechas indicadas. Puedes declarar cuotas en el calendario del paso 3.';box.append(basis);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Datos y límites del escenario';details.append(summary);(r.assumptions||[]).forEach(t=>{const p=document.createElement('p');p.textContent=t;details.append(p)});box.append(details)}for(const a of r.alternatives||[]){const card=document.createElement('section');card.className='po-cash-option';const h=document.createElement('h3');h.textContent=a.title;const p=document.createElement('p');p.textContent='Total propuesto: '+money(a.total)+' EUR · Saldo mínimo resultante: '+money(a.minimum_balance)+' EUR. Sujeto a las mismas hipótesis y aceptación del proveedor.';const text=document.createElement('textarea');text.rows=3;text.readOnly=true;text.setAttribute('aria-label','Texto de negociación: '+a.title);text.value=a.negotiation_text;card.append(h,p,text);if(editable){const apply=document.createElement('button');apply.type='button';apply.textContent='Aplicar y recalcular';apply.onclick=()=>{const form=$('form');Object.entries(a.patch).forEach(([key,value])=>{if(key==='payment_installments'){$('payment-plan-enabled').checked=true;$('payment-plan-rows').replaceChildren();value.forEach(i=>{addPaymentRow();const row=$('payment-plan-rows').lastElementChild;Object.entries(i).forEach(([k,v])=>{row.querySelector('[data-payment-field='+k+']').value=k==='due_date'?stockDate(v):v})});paymentRowsEnabled()}else if(form.elements[key])form.elements[key].value=key.endsWith('date')?stockDate(value):value});form.dispatchEvent(new Event('change',{bubbles:true}));box.scrollIntoView({behavior:'smooth',block:'center'})};card.append(apply)}box.append(card)}if(r.status==='SHORTFALL'&&!r.alternatives?.length){const p=document.createElement('p');p.textContent='No se ha encontrado una alternativa comprobable con el calendario y horizonte disponibles. No se propone un aplazamiento fuera del período analizado.';box.append(p)}if(r.capital_measure){const card=document.createElement('div');card.className='po-cash-option';const h=document.createElement('h3');h.textContent='Medida a estudiar con los socios';const p=document.createElement('p');p.textContent='Aportación mínima teórica: '+money(r.capital_measure.amount)+' EUR, disponible antes del '+stockDate(r.capital_measure.needed_by)+'. Pendiente de aprobación y desembolso; no se suma a la tesorería.';card.append(h,p);box.append(card)}const limit=document.createElement('small');limit.textContent='Escenario orientativo con datos documentales. No acredita conciliación, disponibilidad actual ni viabilidad final. Guardar conserva el estudio; no ejecuta una compra.';box.append(limit);if(editable&&r.status==='PENDING'){const button=document.createElement('button');button.type='button';button.textContent='Revisar parámetros financieros';button.onclick=()=>view('parametros');box.append(button)}}
function schedulePurchaseCash(){const seq=++purchaseCashSequence,dataset=$('dataset').value;clearTimeout(purchaseCashTimer);purchaseCashController?.abort();purchaseCashBox.className='po-cash';purchaseCashBox.textContent='Evaluación pendiente de recalcular con las condiciones actuales…';renderPurchaseCashAlert({status:'PENDING',message:'Recalculando con las condiciones actuales…'});purchaseCashTimer=setTimeout(async()=>{try{if(!state||state.info.dataset_id!==dataset)return;purchaseCashController=new AbortController();const controller=purchaseCashController,timeout=setTimeout(()=>controller.abort(),30000);try{const data=Object.fromEntries(new FormData($('form')));data.dataset_id=dataset;data.documentary_context_fingerprint=state.documentary_context.fingerprint;data.payment_installments=declaredPaymentRows();const r=await api('/api/purchases/cash-preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify(data),signal:purchaseCashController.signal});if(seq!==purchaseCashSequence||dataset!==$('dataset').value)return;renderPurchaseCash(purchaseCashBox,r,true)}finally{clearTimeout(timeout)}}catch(e){if(seq===purchaseCashSequence&&dataset===$('dataset').value)renderPurchaseCash(purchaseCashBox,{status:'PENDING',message:e.name==='AbortError'?'La evaluación no ha respondido a tiempo. Modifica un dato para recalcular; no se ha confirmado capacidad de pago.':e.message},true)}},450)}
$('form').addEventListener('click',event=>{if(event.target.closest('#payment-plan-add,#payment-plan-rows button'))schedulePurchaseCash()});document.querySelector('[data-nav=propuestas]').addEventListener('click',schedulePurchaseCash);$('form').addEventListener('input',schedulePurchaseCash);$('form').addEventListener('change',schedulePurchaseCash);$('dataset').addEventListener('change',schedulePurchaseCash);new MutationObserver(schedulePurchaseCash).observe($('summary'),{childList:true,characterData:true,subtree:true});schedulePurchaseCash();
function renderPurchaseCashSaved(proposal){let box=$('po-cash-saved');if(!box){box=document.createElement('section');box.id='po-cash-saved';$('review-panel').append(box)}if(proposal.cash_orientation_at_save){box.hidden=false;renderPurchaseCash(box,proposal.cash_orientation_at_save,false)}else{box.hidden=true;box.replaceChildren()}}
'''
